/* Skin "t3-chat" (T3 Chat): the tweakcn preset "t3-chat" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="t3-chat" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: system. */
[data-skin="t3-chat"] {
  --background: hsl(300 33% 97%);
  --foreground: hsl(296 56% 21%);
  --card: hsl(300 33% 97%);
  --card-foreground: hsl(296 56% 21%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(296 56% 21%);
  --primary: hsl(333 43% 46%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(314.7 61.6% 85.7%);
  --secondary-foreground: hsl(295.8 40.9% 34.5%);
  --muted: hsl(311 49% 93%);
  --muted-foreground: hsl(296 33% 40%);
  --accent: hsl(314.7 61.6% 85.7%);
  --accent-foreground: hsl(295.8 40.9% 34.5%);
  --destructive: hsl(357.7 43.7% 46.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(305 61% 84%);
  --input: hsl(317 44% 83%);
  --ring: hsl(333.3 71.4% 50.6%);
  --chart-1: hsl(318.4 70.2% 50%);
  --chart-2: hsl(272 82% 40%);
  --chart-3: hsl(197 37% 24%);
  --chart-4: hsl(43 74% 66%);
  --chart-5: hsl(27 87% 67%);
  --sidebar: hsl(290 50% 93%);
  --sidebar-foreground: hsl(327 77% 38%);
  --sidebar-primary: hsl(240 10% 30%);
  --sidebar-primary-foreground: hsl(320 47% 96%);
  --sidebar-accent: hsl(60 7% 97%);
  --sidebar-accent-foreground: hsl(240 10% 30%);
  --sidebar-border: hsl(20 7% 92%);
  --sidebar-ring: hsl(333.3 71.4% 50.6%);
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --radius: 0.5rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(357.7 43.7% 40.7%);
}

:is(.dark, [data-theme="dark"]) [data-skin="t3-chat"],
[data-skin="t3-chat"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(270 15% 13%);
  --foreground: hsl(272 28% 82%);
  --card: hsl(270 14% 17%);
  --card-foreground: hsl(324.5 23.4% 81.6%);
  --popover: hsl(320 23% 5%);
  --popover-foreground: hsl(326 33% 96%);
  --primary: hsl(332 100% 32%);
  --primary-foreground: hsl(329.4 59.5% 84.5%);
  --secondary: hsl(274 15% 21%);
  --secondary-foreground: hsl(270 30% 83%);
  --muted: hsl(272.7 13.9% 15.5%);
  --muted-foreground: hsl(268.8 20.7% 76.3%);
  --accent: hsl(272 20% 27%);
  --accent-foreground: hsl(326 33% 96%);
  --destructive: hsl(350.6 50% 12.5%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(327 8% 21%);
  --input: hsl(312 9% 22%);
  --ring: hsl(333.3 71.4% 50.6%);
  --chart-1: hsl(333 43% 46%);
  --chart-2: hsl(273 55% 55%);
  --chart-3: hsl(30 80% 55%);
  --chart-4: hsl(280 65% 60%);
  --chart-5: hsl(340 75% 55%);
  --sidebar: hsl(309 17% 8%);
  --sidebar-foreground: hsl(327.3 26.2% 83.5%);
  --sidebar-primary: hsl(224.3 76.3% 48%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(318 21% 12%);
  --sidebar-accent-foreground: hsl(240 5% 96%);
  --sidebar-border: hsl(0 0% 0%);
  --sidebar-ring: hsl(333.3 71.4% 50.6%);
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(350.6 50% 6.5%);
}

[data-skin="t3-chat"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="t3-chat"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="t3-chat"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="t3-chat"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="t3-chat"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="t3-chat"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
